/** 숫자 1~13, 조커(J) 글자 템플릿. TemplateGenTest 가 첨부 캡처에서 생성한다. */
object Templates {
    val all: List<Recognizer.Template> by lazy { parse(DATA) }

    fun parse(data: String): List<Recognizer.Template> = data.trim().lines().map { line ->
        val (label, aspect, grid) = line.trim().split(' ')
        Recognizer.Template(label, aspect.toFloat(), FloatArray(grid.length) { (grid[it] - 'a') / 15f })
    }

